INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(72200, 0, 722, 0, 0, 0, 'Razorfen Downs', 'Razorfen Downs lies deep in the Razorfen at the southern edge of the Barrens, entered through the great maw that the quilboar hold to be their boar god''s own. It was long the chief city of the quilboar. Now it belongs to the dead. Withered quilboar, risen from their own kind, guard its bramble halls beside withered battle boars, and further in, skeletons, ghouls and spirits of the bitter cold crowd the winding paths. The living who fight beside them are of the Death''s Head: geomancers who hurl fire, and necromancers armored in bone who wield shadow. Near the entrance, fires burn at a great idol. Deepest of all, on a height above the lowest reaches, the lich Amnennar the Coldbringer keeps his seat, and the air grows colder the nearer one comes to him. Champions come here from Stormwind and from the Undercity, and others come for the living the quilboar drag in from the plains.', 'warcraft.wiki.gg/wiki/Razorfen_Downs_(Classic), official description (crafted from the same vines as the Kraul; the traditional capital city of the quilboar; their high priests the Death''s Head; the lich Amnennar the Coldbringer has taken control and turned the maze of thorns into a bastion of undead might); barrens.json 1722 (the Downs'' entrance as Agamaggan''s maw), pointed to in one phrase; areatrigger_teleport 442 (entrance lands at 2592,1107 z51); zones/razorfen_downs.txt (map 129: 722 only); DB spawns map 129 (faction 152 throughout): Withered Warrior 7327, Spearhide 7332, Withered Battle Boar 7333, Death''s Head Geomancer 7335 near the entrance and the idol (x 2550 to 2600, y 940 to 1070); Withered Reaver 7328 x11, Quilguard 7329 x18, Death''s Head Necromancer 7337 x10 in the middle reaches; Splinterbone skeletons 7343-7346, Skeletal Frostweaver 7341 and Summoner 7342, Boneflayer and Thorn Eater Ghouls 7347/7348, Frozen Soul 7352 and Freezing Spirit 7353 in the western reaches toward Amnennar 7358 at 2403,961 z55; creature_template type: Withered quilboar 6 (undead), Death''s Head Geomancer and Necromancer 7 (humanoid, the living); displays QuillBoarWarrior (Withered) and QuillBoarCaster (Death''s Head); smart_scripts base and module: Geomancer Fireball 9053 and Flame Spike; Necromancer Bone Armor 11445 and Shadow Bolt 9613 in both (the module adds an out-of-combat Summon Skeletal Servant, so servants are not claimed); gameobjects 151951 Idol Oven Fire, 151952 Idol Cup Fire x2, 151973 Idol Mouth Fire at 2582-2587,937-942; quest 3525 (an idol near the entrance); quests 3636 and 3341 (Stormwind and the Undercity send for Amnennar) and 3525 (captives from the Barrens), as premises only'),
(72201, 1, 722, 1, 0, 0, 'The Holding Pens', 'Far from the entrance, past the idol and the hall of the gong, the quilboar of the Downs keep pens for the living. They stand at the far end of the Downs, walled in by bramble, with withered quilboar walking the paths nearby. Few would expect to find anyone still alive in this place, but the pens are not empty. Two men are held in them, and with them an ogre, Sah''rhee. What the quilboar mean to do with the people they carry off from the Barrens, nothing in the pens says.', 'gameobjects 157816-157820 Holding Pen (type 0, door) at 2562-2605, 693-765 z55; creature 8516 Belnistrasz at 2611,731 (display 7851, HumanMale), 8696 Henry Stern at 2603,706 (display 8029, HumanMale), 8767 Sah''rhee at 2567,686 (display 11573, OgreMage), each beside a pen; all faction 35; npc_text 2155 (Sah''rhee: Thank you, little $r; gossip menu 1490), not told: only the captive is shown; waypoint_data 871710 (Belnistrasz''s escort from the pens west and round past the gong hall at 2537-2548,874-894 to the idol at 2575,950): the pens lie beyond the gong and the idol from the entrance; Withered Reaver 7328 and Quilguard 7329 at 2534-2546,739-751'),
(72202, 1, 722, 2, 0, 0, 'The Gong', 'Between the idol near the entrance and the pens at the far end of the Downs, a broad hall opens in the bramble. Necromancers of the Death''s Head stand there among withered reavers and quilguards, and dark corridors lead off from it into the thorns. At the side of the hall hangs a great gong. Nothing marks what it is for, or what might come if someone were to strike it.', 'gameobject 148917 Gong (type 10) at 2552,857 z51; Death''s Head Necromancer 7337 at 2547,858, Withered Quilguard 7329 at 2552,859, Withered Reaver 7328 at 2548,853; creature_summon_groups 148917: the summons come from three corridor points (2487,804; 2527,830; 2542,909); warcraft.wiki.gg/wiki/Tuten''kash (the gong on the side of the room; three strikes)'),
(72203, 2, 722, 3, 0, 0, 'Amnennar the Coldbringer', 'Amnennar the Coldbringer is a lich, and he keeps his seat on a height deep within Razorfen Downs, above the lowest reaches where the dead crowd thickest. A shell of frost clings about him, and spirits of the bitter cold drift through the halls on the way up to him. Anyone who would reach him must first pass the great abomination that lumbers through the depths at the foot of his height.', 'creature 7358, single spawn on map 129 at 2403,961 z55 (Glutton 8567 patrols at z24 below); display 7971, Lich model; type 6; smart_scripts 7358 base and module: Frost Armor 12556 on reset; warcraft.wiki.gg/wiki/Razorfen_Downs_(Classic) official description (the lich Amnennar has taken control of the quilboar); quests 3636 and 3341 (he rules the quilboar of the Downs); stormwind.json 151907 (Benedictus names him), not retold'),
(72204, 2, 722, 4, 0, 0, 'Belnistrasz', 'Belnistrasz is a prisoner of the quilboar, held in their pens deep in Razorfen Downs, who had given himself up for dead, or worse, for a meal for the vermin around him. Freed, he names the danger plainly. The Scourge have brokered some sort of deal with the quilboar here, he says, and this nightmare is the result. Rather than simply flee, he means to make a difference for everyone''s sake, and he asks his rescuers to help him, though it will be dangerous. He gives them an oathstone, to be handed back to him if they agree to help.', 'quest 3523 description (thanks for rescuing me; given myself up for dead, or worse, as a meal for these Scourge-infested vermin; the Scourge have brokered some sort of deal with the quilboar, and this nightmare is a result; rather than flee, make a difference; it is probably dangerous) and log text (hand the Oathstone he gave you back to him); AllowableRaces 0, QuestType 2, flags 0; creature 8516, single spawn on map 129 at 2611,731 beside Holding Pen 157817; display 7851 (HumanMale); ScriptName npc_belnistrasz'),
(72205, 2, 722, 5, 0, 0, 'Mordresh Fire Eye', 'Mordresh Fire Eye is a towering skeleton, twice the size of a common one, who keeps to the far reaches of the Downs, not far from the pens where the quilboar hold their captives. He is no mindless thing of bone. He has a voice of his own, and a name that speaks of fire in a place where the dead mostly bring the cold.', 'creature 7357, single spawn on map 129 at 2467,671 z63 (the pens at 2562-2605,693-765); display 8055, SkeletonNaked model at scale 2.0; type 6; creature_text 7357 groups 0 (We will enslave the quilboar), 1 (We will spread across this barren land), 2 (Soon, the Scourge will rule the world), type 12 say; smart_scripts 7357 (base; not touched by the module): out of combat every 36 seconds says lines 0, 1 and 2'),
(72206, 2, 722, 6, 0, 0, 'Glutton', 'Glutton is a hulking abomination stitched together from dead flesh, larger than any of the ghouls around it. It lumbers through the lowest reaches of the Downs, at the foot of the height where the lich keeps his seat, and anyone climbing toward Amnennar must pass its way. A cloud of disease hangs about it at all times, a reek of rot that sickens anyone who comes too near.', 'creature 8567, single spawn on map 129 at 2469,1007 z24, MovementType 2 (patrol), below Amnennar 7358 at 2403,961 z55; display 7864, FleshGolem model at scale 1.45; type 6; smart_scripts 8567 base and module: Disease Cloud 12627 on reset (Nature damage to nearby enemies); warcraft.wiki.gg/wiki/Glutton (an abomination that patrols the lower tier below Amnennar)'),
(72207, 3, 722, 7, 0, 0, 'Extinguishing the Idol', 'Near the entrance of Razorfen Downs stands an idol, and Belnistrasz has learned what it is for. It is an oven, a macabre one: in it the quilboar consume the captives they carry off from the Barrens. He can shut the idol down and bind the quilboar from ever using it again, by a ritual, but not alone. He asks to be escorted to the idol and guarded once he begins, for while the ritual holds him he will barely be able to speak, let alone defend himself. If the quilboar bring him down, he warns, it is all over.', 'quest 3525 description (near the entrance is an idol that functions as a macabre oven; they literally consume their abductees from the Barrens; shut down the idol and bind them from using it again; escort me; I will barely be able to communicate, let alone defend myself; if they take me down it is all over) and log text; AllowableRaces 0, QuestType 2, flags 2, PrevQuestID 3523; gameobjects 151951 Idol Oven Fire, 151952 Idol Cup Fire, 151973 Idol Mouth Fire at 2582-2587,937-942; entrance at 2592,1107'),
(72208, 3, 722, 8, 2, 0, 'An Unholy Alliance', 'On the body of Charlga Razorflank, the crone of Razorfen Kraul, lies a small scroll. It is a letter, addressed to My Lady and signed by Ambassador Malcin. He reminds her of what he has offered: the chance to take the Barrens and the lands beyond. In return he asks only her aid, by which he means the freedom to act in the area. He would talk further, for they have great power and will share it with those wise enough to join them. For now, he writes, he will remain outside Razorfen Downs. The scroll is to be carried to the Royal Quarter of the Undercity.', 'quest 6522 description and quest 14352 description (the same letter: My Lady; the opportunity to take the Barrens and the lands beyond; aid meaning the freedom to take action in the area; great power, shared with those wise enough to join us; I will remain outside Razorfen Downs; Ambassador Malcin); both AllowableRaces 690, QuestType 2, flags 0; item 17008 Small Scroll starts 6522; item 49205 Small Scroll starts 14352; creature_loot_template 4421 (Charlga) drops 49205 for the Horde (conditions 1/4421/49205, team 67); mod-individual-progression zone_undercity.sql replaces it with 17008 (same condition); quest 6522 and 14352 log text (take the Small Scroll to the Undercity; module 6522 text: to Varimathras in the Undercity); razorfen_kraul.json 49103 notes (the scroll left to this file)'),
(72209, 3, 722, 9, 0, 0, 'A Host of Evil', 'Outside the maw of Razorfen Downs, the night elf Myriam Moonsinger keeps her watch on the undead diplomat there, and she has drawn her own conclusion. The Forsaken, as far as she has seen, do not pass on their illness to others, and so she has begun to think this one is of the Scourge. For now he is not her concern. The growing ranks around him are: Razorfen battleguards and thornweavers, and cultists of the Death''s Head, who creep from the shadows every day. She is not strong enough to fight them alone, and she asks for help in hunting them.', 'quest 6626 description (the Forsaken do not pass on their illness; this diplomat seems to be granting undeath to would-be followers; I am beginning to think he is one of the Scourge; my concern is the growing ranks around him; they creep from the shadows daily; not powerful enough to fight them on my own) and log text (Razorfen Battleguard, Razorfen Thornweavers, Death''s Head Cultists; Myriam Moonsinger near the entrance to Razorfen Downs); AllowableRaces 0, QuestType 2, flags 8; creature 12866 Myriam Moonsinger on map 1 at -4802,-2344 (display 12964, NightElfFemale), outside the Downs; Ambassador Malcin 12865 stands about 70 yards away at -4847,-2294; barrens.json 1722 (the night elf watcher and the undead diplomat), pointed to in one phrase');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(72200, 1, 0, 255, 'Ragglesnout does not always stand in the Downs, but when he is there he is hard to miss: a quilboar of great size who fights with shadow. He hurled bolts of darkness, laid a word of pain on his foes that gnawed at them, and seized a foe''s mind to turn it against its friends, and he had healing magic as well. None of it saved him. He fell among the thorns.', 'creature 7354 Ragglesnout, single spawn on map 129 at 2365,905 z29 (guid 247108, random movement 5 yards); rank 2, type 7; display 11382, QuillBoar model at scale 2.0; smart_scripts 7354: despawn on AI init with event_chance 70 (base event_flags 512, SMART_EVENT_FLAG_WHILE_CHARMED per SmartScriptMgr.h, not debug only; module event_flags 0, same chance), so he stands in about three instances in ten; smart_scripts 7354 base and module: Shadow Bolt 12471, Shadow Word: Pain 11639, Dominate Mind 7645, Heal 12039 (base: when he himself is under 40 percent, on creatures in range; module: on a friend under 40 percent), so only that he could heal is told (Spell.dbc descriptions)'),
(72201, 1, 0, 255, 'One of the two men is Henry Stern, a cook and an alchemist from Stormwind. He came to the Barrens looking for local herbs and recipes for his uncle Angus, and the quilboar caught him. He thanks whoever freed him with all his heart. If no one had come along, he says, he is sure he would have ended up in their stew pot.', 'npc_text 2113 (gossip menu 1443 of creature 8696: a cook and an alchemist from Stormwind, looking for local herbs and recipes for his uncle Angus when the quilboar captured him; would have ended up in their stew pot); creature 8696, single spawn on map 129 at 2603,706 z55'),
(72202, 1, 0, 255, 'The gong was answered. At its first sounding tomb fiends, small crypt fiends, poured out of the corridors and threw themselves at whoever stood near. When they were dead it rang again, and larger tomb reavers came, binding their foes in webs. At the third sounding Tuten''kash crawled out of the dark, a crypt fiend of monstrous size. Its curse dragged at every spell and blow around it and its webs pinned all before it, but it died in the hall, and the gong fell silent.', 'creature 7355 Tuten''kash: no spawn, summoned only by the gong (creature_summon_groups 148917 group 3); display 7845, CryptFiend model at scale 2.5, type 6; smart_scripts 148917 (source 1): gossip hello summons groups 1 to 3 in turn, gated by counters set by the deaths of Tomb Fiends 7349 (group 1, ten; CryptFiend scale 0.5) and Tomb Reavers 7351 (group 2, four; CryptFiend scale 1.0); smart_scripts 7349 and 7351: set in combat with zone on reset; Tomb Reaver Web 745; smart_scripts 7355: Curse of Tuten''kash 12255 (reduces casting speed and slows attacks of nearby enemies), Web Spray 12252 (immobilizes enemies in a cone in front); on death sets instance data, and instance_razorfen_downs.cpp makes the gong unselectable once done; not touched by the module'),
(72203, 1, 0, 255, 'The Downs did not always seem so dark. Once it looked like the home of simple quilboar and little threat to anyone, but what has been found there since is far more serious. The quilboar of the Downs have made a pact with the Scourge, and the lich Amnennar the Coldbringer rules them now.', 'quest 3636 description (once the home of simple quilboar; a pact was made with the Scourge, creating creatures far worse; now ruled by the lich Amnennar the Coldbringer); quest 3341 description (first observations revealed little threat; the quilboar of Razorfen Downs have aligned themselves with the Scourge; a lich named Amnennar rules them now)'),
(72203, 2, 0, 255, 'To any who have heard Falfindel Waywarder at Thalanaar, this may be the answer he sought. He feared that treachery lay behind the corruption of the resting place of Agamaggan, long held to be pure, and here the boar god''s own people have struck a bargain with the Scourge.', 'quest 3636 description (a pact was made with the Scourge); quest 1101 reward text (Falfindel hopes to learn what corrupted the resting place of Agamaggan and fears the answer lies in treachery; AllowableRaces 1101, Alliance only); feralas.json 35725 part 2 and 35731 part 2, pointed to in one phrase; the link between the corruption and the pact is offered as a possibility, since no quest text makes it'),
(72203, 3, 0, 255, 'In the Undercity, Andrew Brownell of the Magic Quarter says more. The lich controls the quilboar''s every move by the power of his vast mind, and he holds a direct link of thought to Ner''zhul himself. That bond must be severed, Brownell says, and an end must come to the Coldbringer.', 'quest 3341 description (using the power of his massive consciousness to control their every move; a direct telepathic link to Ner''zhul; we must sever this bond; an end must come to the Coldbringer) and QuestCompletionLog (Andrew Brownell at the Magic Quarter in the Undercity); AllowableRaces 690'),
(72203, 4, 0, 255, 'Amnennar met intruders with a promise that they would never leave this place alive. He struck with frost, freezing foes where they stood and hurling them back from him. As his wounds mounted he named himself the hand of the Lich King and drew wraiths out of the freezing air, calling on his servants and the spirits to attend their master. The Coldbringer fell on his height all the same.', 'creature_text 7358 groups 0 (You''ll never leave this place alive), 3 (I am the hand of the Lich King), 5 (begins to summon wraiths out of the freezing cold air), 1 (To me, my servants) and 2 (Come, spirits - attend your master); smart_scripts 7358 base and module (same sequence): aggro line 0; at 70 percent line 3; at 55 percent emote 5, line 1 and Summon Frost Spectres 12642; at 30 percent emote 5, line 2 and Summon Frost Spectres; Frostbolt 15530, Frost Nova 15531, Amnennar''s Wrath 13009 (knocks an enemy back); the kill line 4 (Too easy) is not quoted, since it needs a death'),
(72203, 5, 0, 255, 'In the Cathedral of Light, Archbishop Benedictus gave his thanks. The Scourge, he said, will now think twice before it tries to bolster its ranks again, and he blessed in the name of the Light the one who had ended the lich.', 'quest 3636 reward text (the Scourge will now think twice before attempting to bolster its ranks again; may you be blessed by the Light); AllowableRaces 1101'),
(72203, 6, 0, 255, 'Andrew Brownell had made plain what was at stake: any attempt by the Scourge to bolster its ranks had to be stopped. When the lich''s skull was laid before him, he was satisfied. The loyalty of a lich is unswerving, he said; let the Scourge learn that such loyalty brings them only destruction.', 'quest 3341 log text (kill Amnennar and return his skull), request text (we must stop any attempt by the Scourge to bolster their ranks) and reward text (the loyalty of a Lich is unswerving; such loyalty will only bring them destruction)'),
(72204, 1, 0, 255, 'Belnistrasz cares nothing for politics, he says. Whether his helpers are of the Horde or the Alliance means nothing to him: what matters is stamping out direct and dire threats to all the races, and there is a large one here. He is not from these parts, he admits, and among his kind an oathstone is a bond of agreement. When it came back to him he was delighted, and set about telling his new allies what has been going on.', 'quest 3523 request text (not one for politics; Horde or Alliance; squelching direct and dire threats to all the races, and a large one in here; not from around these parts; an oathstone important to people of my kind as a bond of agreement) and reward text (I thought you looked to be the heroic type; let me bring you up to speed)'),
(72204, 2, 0, 255, 'In the brazier Belnistrasz left behind, a vision waited. Those who gazed into its flame saw a great-winged red dragon fill their minds, and heard Belnistrasz''s voice, rougher now, speaking to them directly. They were the heroes he had hoped for, he said. The butchery the quilboar had worked here was a thing of the past, and his faith in mortals had been renewed once more.', 'quest 3525 reward text (Belnistrasz''s sudden departure has left a burning brazier; the image of a great-winged red dragon fills your mind; a more graveled version of Belnistrasz''s voice; the heroes I had hoped you would be; the butchery a thing of the past; my faith in mortals renewed); gameobject 152097 Belnistrasz''s Brazier (type 2, questgiver), summoned by npc_belnistrasz at the end of the ritual; quest 3525 ends at it (QuestCompletionLog); warcraft.wiki.gg/wiki/Belnistrasz (a red dragon of the Red Dragonflight in human form)'),
(72205, 1, 0, 255, 'Those who came near him heard his boasts: the Scourge would enslave the quilboar, spread across this barren land and soon rule the world. He spoke of the quilboar as slaves to be taken, not as allies. He met intruders with a cry to his brethren to slay them for the Scourge, and the dead nearby came at his call. He answered with fire, hurling it and loosing bursts of flame on any who came close, but he fell all the same.', 'creature_text 7357 groups 0 (We will enslave the quilboar), 1 (We will spread across this barren land), 2 (Soon, the Scourge will rule the world), type 12 say, said out of combat on a timer, so heard by anyone who comes near enough to fight him; group 3 (Slay them, my brethren! For the Scourge!), type 14 yell, said on aggro; smart_scripts 7357: on aggro line 3 and Call for Help 50 yards; Fireball 12466; Fire Nova 12470 within 9 yards'),
(72206, 1, 0, 255, 'Glutton bellowed as it struck that it smelled the stench of the living. As the fight wore on it grew hungry, then very hungry, and fell into a frenzy, lashing out faster and harder in its need to feed. It never fed. The abomination collapsed in the depths of the Downs, below the lich''s height.', 'creature_text 8567 groups 0 (Me smell stench of the living), 2 (is getting hungry), 3 (is getting VERY hungry); group 1 (Me feast on you all) is the kill line and is not quoted; smart_scripts 8567 base: line 0 on aggro, line 2 at 30-50 percent, line 3 and Frenzy 12795 at 0-20 percent; module: line 0 on aggro, Frenzy with line 2 at 30-50 percent and with line 3 at 0-15 percent; both end in a frenzy, so only that is told'),
(72207, 1, 0, 255, 'The quilboar did not let the ritual go unchallenged. Last of all those sent against it came Plaguemaw the Rotting, a great quilboar rotting on his feet. His stench hung over the idol, sapping the strength and quickness of all who breathed it and choking off their spells. He fell beside the idol all the same.', 'creature 7356 Plaguemaw the Rotting: no spawn; summoned by npc_idol_room_spawner when its data is 7, the eighth and last spawner of the ritual, about four minutes in; data 7 summons him alone, without boars or geomancers (razorfen_downs.cpp); display 6124, QuillBoar model at scale 1.5; type 7; smart_scripts 7356 (not touched by the module): Putrid Stench 12946 (reduces nearby enemies'' Strength and Agility and prevents spellcasting)'),
(72207, 2, 0, 255, 'Belnistrasz led the way from the pens to the idol, warning his escort to stay close, for the fiends here leap out of the shadows. At the idol he began: the ritual would take about five minutes. The Downs answered with wave after wave of withered battle boars, Death''s Head geomancers and withered quilguards, while he called out the minutes as the power built. Then it was done. The idol''s fires went out for good, and Belnistrasz was gone, leaving a burning brazier behind.', 'creature_text 8516 groups 0 (stay close; these fiends will jump right out of the shadows), 1 (about five minutes; keep the vermin off of me), 2 to 4 (three, two, one minutes left), 5 (that''s it, we made it; the idol fires are about to go out for good); razorfen_downs.cpp npc_belnistrasz: escort path 871710 from the pens to the idol (point 18 at 2575,950); seven waves of Withered Battle Boar 7333, Death''s Head Geomancer 7335 and Withered Quilguard 7329 at 35 second intervals, then Plaguemaw; at the end the idol fires 151951, 151952 and 151973 deleted, brazier 152097 summoned, quest completed for players in range, Belnistrasz despawned; the camera shake 12816 is a dummy with no script in this core, so no shaking is told; quest 3525 reward text (Belnistrasz''s sudden departure has left behind a burning brazier)'),
(72208, 1, 0, 255, 'In the Royal Quarter, Varimathras knew the insignia on the scroll. Malcin, he said, was one of the Scourge''s plagued servants, once a human diplomat to the kingdom of Lordaeron, before things changed. It seems the Scourge are not content with one continent, and if they are trying to gain a foothold in Kalimdor, it falls to the Undercity to act.', 'quest 6522 reward text (I recognize the insignia; found on the crone who reigns over Razorfen Kraul; the Scourge aren''t content with one continent; Ambassador Malcin one of the Scourge''s plagued servants, a human diplomat to the kingdom of Lordaeron before things changed; up to us to act); creature_questender 2425 Varimathras for 6522 (base data); mod-individual-progression zone_undercity.sql spawns Varimathras (guid 602425) in the Royal Quarter in phase IPP_PHASE_II (before the Battle for the Undercity, IndividualProgression.cpp AREA_UNDERCITY) and removes 6522 from disables'),
(72208, 2, 0, 255, 'Malcin must be slain, Varimathras decided, and his mission made a failure in the eyes of the Lich King. His presence explains much of what the Forsaken have found around the Downs. Some of the quilboar there have grown frightfully powerful, while showing signs of the Plague in their own way: surely the mark of some deal they have struck.', 'quest 6521 description (this ambassador must be slain, his mission a failure in the eyes of the Lich King; some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way; a sign of some sort of deal they have struck); AllowableRaces 690, QuestType 2, flags 8, PrevQuestID 6522; creature_queststarter 2425 for 6521 (base data); reachable only with mod-individual-progression (disables removed in zone_undercity.sql)'),
(72208, 3, 0, 255, 'Malcin was found where he had said he would be, outside Razorfen Downs, and slain, and his head was carried to the Undercity. The Scourge must not take a foothold on Kalimdor, Varimathras said. The one hopeful sign was the crone: she seemed uncorrupted, as if she knew in her spirit that the Barrens would never truly be hers if she took the Scourge''s deal. With Malcin dead the Scourge''s advance was halted, and the Dark Lady sent her thanks. How far their influence reaches within the Downs, no one yet knows.', 'quest 6521 log text (bring Ambassador Malcin''s Head), request text (we cannot afford to allow the Scourge to take a foothold on Kalimdor; the crone seemed uncorrupted; the Barrens would not truly be hers if she were to agree to their deal) and reward text (now that Malcin is dead the Scourge''s advances will be halted; the Dark Lady thanks you; we do not know the extent of the Scourge''s influence within the Downs); creature 12865 Ambassador Malcin, single spawn on map 1 at -4847,-2294 z87, outside the Downs; creature_loot_template 12865 item 17009 Ambassador Malcin''s Head'),
(72208, 4, 13, 255, 'In the Royal Quarter, Bragor Bloodfist knew the insignia on the scroll from his time in Northrend, and he had no doubts. Malcin is plainly one of the Lich King''s servants, and that makes him a target. Bragor will not let the Scourge get a foothold here: they are not going to take Kalimdor.', 'quest 14352 reward text (I''ve seen the insignia on this scroll before during my time in Northrend; this Malcin is one of the Lich King''s servants, and that makes him a target; they''re not going to take Kalimdor); creature_questender 36273 Bragor Bloodfist; undercity.json 149706 (Bragor, requiredState 13), named only'),
(72208, 5, 13, 255, 'Bragor''s contacts in Orgrimmar had sent word that their scouts found signs of the Plague around the Downs, and quilboar showing it too, and far more powerful for it. Malcin was found outside Razorfen Downs and slain, and his head went to Bragor. It was a deed that did the Horde proud, he said, keeping the Scourge from setting down roots on its soil. What they have done in the Downs is not yet known, but it will be: they cannot slink around in the dark forever.', 'quest 14353 description (my contacts in Orgrimmar tell me their scouts have found signs of the Plague down there; the quilboar are showing signs of being plagued too, much more powerful; find this Malcin and kill him), log text (bring Ambassador Malcin''s Head) and reward text (you''ve done the Horde proud by stopping the Scourge from setting down roots on our soil; we may not know everything they''ve done in the Downs, but we''ll find out; they can''t slink around in the dark forever); creature 12865 Ambassador Malcin on map 1 outside the Downs; ACCEPT 14353 is undercity.json''s (149706, 149707) and is not used'),
(72209, 1, 0, 255, 'The hunt left Myriam in no doubt. Seeing even this small sample of the diplomat''s power, she says, has removed any doubt she had that the Scourge are one of the greatest threats this world has ever seen. She will go on studying him and the quilboar around him. For those who want a greater challenge she points to the cave nearby, shaped like the maw of a great boar: inside, she is sure, they will find one.', 'quest 6626 request text (seeing this small sample of the diplomat''s power removes any doubt that the Scourge are one of the greatest threats this world has ever seen) and reward text (I will continue my study of this diplomat and the rest of the quilboar; head into the cave that looks like a great boar maw; greater challenges inside)');
